**parser.js**

```js
window.DepTool = window.DepTool || {};
(function (ns) {
  const SEPARATORS = ['->', '<-', '=>', '<=', ':'];

  function stripComment(line) {
    // remove // and # comments, but not inside quotes
    let inQ = null;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (inQ) { if (ch === inQ) inQ = null; continue; }
      if (ch === '"' || ch === "'" || ch === '`') { inQ = ch; continue; }
      if (ch === '#') return line.slice(0, i);
      if (ch === '/' && line[i+1] === '/') return line.slice(0, i);
    }
    return line;
  }

  function cleanName(raw) {
    let s = raw.trim();
    // strip matching surrounding quotes repeatedly
    let changed = true;
    while (changed && s.length >= 2) {
      changed = false;
      const f = s[0], l = s[s.length-1];
      if ((f === '"' && l === '"') || (f === "'" && l === "'") || (f === '`' && l === '`')) {
        s = s.slice(1, -1).trim();
        changed = true;
      }
    }
    return s;
  }

  function splitTargets(s) {
    // split by , 、 ; respecting quotes
    const parts = []; let cur = ''; let inQ = null;
    for (const ch of s) {
      if (inQ) { cur += ch; if (ch === inQ) inQ = null; continue; }
      if (ch === '"' || ch === "'" || ch === '`') { inQ = ch; cur += ch; continue; }
      if (ch === ',' || ch === '，' || ch === '、' || ch === ';' || ch === '；') { parts.push(cur); cur = ''; continue; }
      cur += ch;
    }
    parts.push(cur);
    return parts.map(cleanName).filter(x => x.length > 0);
  }

  function findSeparator(line) {
    // find first separator outside quotes; check two-char ones first
    let inQ = null;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (inQ) { if (ch === inQ) inQ = null; continue; }
      if (ch === '"' || ch === "'" || ch === '`') { inQ = ch; continue; }
      const two = line.substr(i, 2);
      if (two === '->' || two === '=>' || two === '<-' || two === '<=') return { idx: i, sep: two };
      if (ch === ':') return { idx: i, sep: ':' };
    }
    return null;
  }

  ns.parse = function (text) {
    const edgeSet = new Set();
    const edges = [];
    const nodeSet = new Set();
    const isolated = new Set();
    const lines = text.split(/\r?\n/);
    for (let rawLine of lines) {
      let line = stripComment(rawLine).trim();
      if (!line) continue;
      const sepInfo = findSeparator(line);
      if (!sepInfo) {
        const name = cleanName(line);
        if (name) { nodeSet.add(name); isolated.add(name); }
        continue;
      }
      const left = line.slice(0, sepInfo.idx);
      const right = line.slice(sepInfo.idx + sepInfo.sep.length);
      let sources = splitTargets(left);
      let targets = splitTargets(right);
      if (sepInfo.sep === '<-' || sepInfo.sep === '<=') {
        const t = sources; sources = targets; targets = t;
      }
      for (const s of sources) {
        for (const t of targets) {
          nodeSet.add(s); nodeSet.add(t);
          isolated.delete(s); isolated.delete(t);
          const key = s + '\u0001' + t;
          if (!edgeSet.has(key)) { edgeSet.add(key); edges.push([s, t]); }
        }
      }
    }
    // isolated = nodes never in any edge
    const inEdge = new Set();
    for (const [s, t] of edges) { inEdge.add(s); inEdge.add(t); }
    const isolatedNodes = [...nodeSet].filter(n => !inEdge.has(n)).sort();
    return { nodes: [...nodeSet].sort(), edges, isolated: isolatedNodes };
  };
})(window.DepTool);
```

