Johnson's cycles:

```js
  ns.findCycles = function (nodes, edges) {
    // self loops
    const selfLoops = new Set();
    const adjMap = new Map();
    for (const n of nodes) adjMap.set(n, new Set());
    for (const [a, b] of edges) {
      if (a === b) selfLoops.add(a);
      else adjMap.get(a).add(b);
    }
    const cycles = [];
    const seen = new Set();
    function canonical(cyc) {
      // cyc: array of nodes, no repeated start at end
      let best = null;
      for (let i = 0; i < cyc.length; i++) {
        const rot = cyc.slice(i).concat(cyc.slice(0, i)).join('\u0001');
        if (best === null || rot < best) best = rot;
      }
      return best;
    }
    function addCycle(cyc) {
      const key = canonical(cyc);
      if (!seen.has(key)) { seen.add(key); cycles.push(cyc.slice()); }
    }
    for (const s of selfLoops) addCycle([s]);

    // Johnson's algorithm
    const sortedNodes = [...nodes].sort();
    const order = new Map(sortedNodes.map((n, i) => [n, i]));
    // subgraph induced on nodes with order >= start order
    for (let si = 0; si < sortedNodes.length; si++) {
      const start = sortedNodes[si];
      // subgraph nodes: order >= si
      const subNodes = sortedNodes.slice(si);
      const subAdj = new Map();
      for (const n of subNodes) {
        const list = [];
        for (const m of adjMap.get(n)) if (order.get(m) >= si) list.push(m);
        list.sort();
        subAdj.set(n, list);
      }
      // find SCCs of subgraph; only proceed if start is in a nontrivial SCC
      const sccs = tarjanOn(subNodes, subAdj);
      const startScc = sccs.find(c => c.includes(start) && c.length > 1);
      if (!startScc) continue;
      // restrict to that SCC
      const inScc = new Set(startScc);
      const adj = new Map();
      for (const n of startScc) adj.set(n, subAdj.get(n).filter(m => inScc.has(m)));
      // circuit finding from start
      const blocked = new Set();
      const B = new Map(startScc.map(n => [n, new Set()]));
      const stack = [];
      function unblock(u) {
        blocked.delete(u);
        for (const w of B.get(u)) { if (blocked.has(w)) unblock(w); }
        B.get(u).clear();
      }
      function circuit(v) {
        let found = false;
        stack.push(v);
        blocked.add(v);
        for (const w of adj.get(v)) {
          if (w === start) { addCycle(stack.slice()); found = true; }
          else if (!blocked.has(w)) { if (circuit(w)) found = true; }
        }
        if (found) unblock(v);
        else for (const w of adj.get(v)) B.get(w).add(v);
        stack.pop();
        return found;
      }
      circuit(start);
    }
    // sort cycles deterministically: by length then canonical string
    cycles.sort((c1, c2) => c1.length - c2.length || canonical(c1) < canonical(c2) ? -1 : ...);
    return cycles; // each stored in canonical rotation (smallest first)
  };
```

Note: Johnson's as written — standard version iterates s over vertices, builds subgraph of vertices >= s, finds SCCs, picks SCC with least vertex, and if that least vertex is s, runs circuit. My variant: check if start is in a nontrivial SCC of the subgraph; run circuit(start). This is correct: each elementary circuit has a least vertex (in the ordering), and it will be found exactly when si = that least vertex, because then all circuit nodes are >= si and start is the least, in the same SCC. For si less than the least vertex of a given circuit, start isn't on that circuit. So each circuit found exactly once. Dedupe via canonical key is belt-and-suspenders.

