window.DepTool = window.DepTool || {};
(function (ns) {
  'use strict';

  function cmp(a, b) { return a < b ? -1 : a > b ? 1 : 0; }

  // Tarjan SCC, deterministic order
  ns.findSCCs = function (nodes, edges) {
    const adj = new Map();
    for (const n of nodes) adj.set(n, []);
    for (const e of edges) { adj.get(e[0]).push(e[1]); }
    for (const n of nodes) adj.get(n).sort(cmp);

    const index = new Map(), low = new Map(), onStack = new Set(), stack = [];
    const sccs = [];
    let counter = 0;

    function strongconnect(v) {
      index.set(v, counter); low.set(v, counter); counter++;
      stack.push(v); onStack.add(v);
      for (const w of adj.get(v)) {
        if (!index.has(w)) { strongconnect(w); low.set(v, Math.min(low.get(v), low.get(w))); }
        else if (onStack.has(w)) { low.set(v, Math.min(low.get(v), index.get(w))); }
      }
      if (low.get(v) === index.get(v)) {
        const scc = [];
        let w;
        do { w = stack.pop(); onStack.delete(w); scc.push(w); } while (w !== v);
        scc.sort(cmp);
        sccs.push(scc);
      }
    }
    const sorted = [...nodes].sort(cmp);
    for (const v of sorted) if (!index.has(v)) strongconnect(v);
    sccs.sort((a, b) => cmp(a[0], b[0]));
    return sccs;
  };
