          }
          if (found) unblock(v);
          else for (const w of cadj.get(v)) B.get(w).add(v);
          stack.pop();
          return found;
        }
        circuit(start);
      }
    }
    cycles.sort((a, b) => a.length - b.length || cmp(a.join('\u0001'), b.join('\u0001')));
