Layers:

```js
  ns.computeLayers = function (components, compAdj) {
    const n = components.length;
    const layer = new Array(n).fill(-1);
    function dfs(u) {
      if (layer[u] >= 0) return layer[u];
      let best = 0;
      for (const v of compAdj[u]) best = Math.max(best, dfs(v) + 1);
      layer[u] = best;
      return best;
    }
    for (let i = 0; i < n; i++) dfs(i);
    return layer;
  };
```

topoOrder (build order: dependencies first):

```js
  ns.topoOrder = function (components, compAdj, compPred) {
    const n = components.length;
    const remaining = compAdj.map(s => s.size); // out-degree = unmet dependencies
    const key = components.map(c => c.members[0]);
    const ready = [];
    for (let i = 0; i < n; i++) if (remaining[i] === 0) ready.push(i);
    const order = [];
    while (ready.length) {
      ready.sort((a, b) => cmp(key[a], key[b]));
      const u = ready.shift();
      order.push(u);
      for (const p of compPred[u]) {
        remaining[p]--;
        if (remaining[p] === 0) ready.push(p);
      }
    }
    return order;
  };
```

