  ns.findCycles = function (nodes, edges) {
    // self loops
    const selfLoops = new Set();
    const adjMap = new Map();
    for (const n of nodes) adjMap.set(n, new Set());
    for (const [a, b] of edges) {
      if (a === b) selfLoops.add(a);
      else adjMap.get(a).add(b);
