  function canonicalCycle(cyc) {
    let bestIdx = 0;
    for (let i = 1; i < cyc.length; i++) if (cyc[i] < cyc[bestIdx]) bestIdx = i;
    return cyc.slice(bestIdx).concat(cyc.slice(0, bestIdx));
  }
  ns.canonicalCycle = canonicalCycle;

  ns.findCycles = function (nodes, edges, sccs) {
    const selfLoop = new Set();
    const adj = new Map();
    for (const n of nodes) adj.set(n, new Set());
    for (const [a, b] of edges) {
      if (a === b) selfLoop.add(a);
      else adj.get(a).add(b);
    }
    const cycles = [];
    const seen = new Set();
    function addCycle(cyc) {
      const c = canonicalCycle(cyc);
      const key = c.join('\u0001');
      if (!seen.has(key)) { seen.add(key); cycles.push(c); }
    }
    for (const s of [...selfLoop].sort(cmp)) addCycle([s]);

    // Johnson: only nontrivial SCCs can contain circuits
    const nonTrivial = sccs.filter(s => s.length > 1);
    for (const scc of nonTrivial) {
      const members = [...scc].sort(cmp);
      const inScc = new Set(members);
      const fullAdj = new Map();
      for (const m of members) {
        fullAdj.set(m, [...adj.get(m)].filter(x => inScc.has(x)).sort(cmp));
      }
      for (let si = 0; si < members.length; si++) {
        const start = members[si];
        const subNodes = members.slice(si);
        const subSet = new Set(subNodes);
        const subAdj = new Map();
        for (const n of subNodes) subAdj.set(n, fullAdj.get(n).filter(x => subSet.has(x)));
        // SCCs of subgraph (iterative Tarjan small)
        const subSccs = tarjan(subNodes, subAdj);
        const startScc = subSccs.find(c => c.length > 1 && c.includes(start));
        if (!startScc) continue;
        const inC = new Set(startScc);
        const cadj = new Map();
        for (const n of startScc) cadj.set(n, subAdj.get(n).filter(x => inC.has(x)));
        const blocked = new Set();
        const B = new Map();
        for (const n of startScc) B.set(n, new Set());
        const stack = [];
        function unblock(u) {
          blocked.delete(u);
          for (const w of B.get(u)) if (blocked.has(w)) unblock(w);
          B.get(u).clear();
        }
        function circuit(v) {
          let found = false;
          stack.push(v);
          blocked.add(v);
          for (const w of cadj.get(v)) {
            if (w === start) { addCycle(stack.slice()); found = true; }
            else if (!blocked.has(w)) { if (circuit(w)) found = true; }
          }
          if (found) unblock(v);
          else for (const w of cadj.get(v)) B.get(w).add(v);
          stack.pop();
          return found;
        }
        circuit(start);
      }
    }
    cycles.sort((a, b) => a.length - b.length || cmp(a.join('\u0001'), b.join('\u0001')));
    return cycles;
  };

  function tarjan(nodes, adj) { ... same as findSCCs but on given adj ... }
