ns.computeLayout = function (model) {
  const { components, layers, isoCompIds, parsed } = model;
  const nodeW = name => Math.max(70, name.length * 8 + 28);
  // cyclic comp grid
  const compBox = new Map(); // id -> {x,y,w,h}
  const nodePos = new Map();
  const layerOf = layers;
  const maxLayer = Math.max(0, ...layers.filter((_, i) => !isoCompIds.has(i)));
  const byLayer = [];
  for (let l = 0; l <= maxLayer; l++) byLayer.push([]);
  components.forEach((c, i) => {
    if (isoCompIds.has(i)) return;
    byLayer[layerOf[i]].push(i);
  });
  for (const arr of byLayer) arr.sort((a, b) => cmp(components[a].members[0], components[b].members[0]));

  // measure
  const COMP_LABEL = 22, PAD = 14, GAP = 12, LAYER_GAP = 90, COMP_GAP = 34;
  function measureComp(c) {
    if (!c.cyclic) {
      const w = nodeW(c.members[0]);
      return { w, h: 34, cols: 1 };
    }
    const n = c.members.length;
    const cols = Math.ceil(Math.sqrt(n));
    const rows = Math.ceil(n / cols);
    const widths = c.members.map(nodeW);
    const cw = Math.max(...widths);
    const w = cols * cw + (cols - 1) * GAP + 2 * PAD;
    const h = COMP_LABEL + rows * 34 + (rows - 1) * GAP + 2 * PAD;
    return { w, h, cols, cw };
  }
  const sizes = components.map(c => measureComp(c));
  const layerH = byLayer.map(arr => arr.length ? Math.max(...arr.map(i => sizes[i].h)) : 0);
  const layerW = byLayer.map(arr => arr.reduce((s, i) => s + sizes[i].w, 0) + Math.max(0, arr.length - 1) * COMP_GAP);
  const isoList = parsed.isolated;
  const isoCols = Math.max(1, Math.ceil(Math.sqrt(isoList.length * 2)));
  ... compute iso region size ...
  const width = Math.max(200, ...layerW, isoWidth + 2*PAD);
  // y positions
  const y0 = 30;
  let y = y0;
  const layerY = [];
  for (let l = 0; l <= maxLayer; l++) { layerY.push(y); y += layerH[l] + LAYER_GAP; }
  // place comps centered
  for (let l = 0; l <= maxLayer; l++) {
    let x = (width - layerW[l]) / 2;
    for (const i of byLayer[l]) {
      const s = sizes[i];
      const bx = x, by = layerY[l];
      compBox.set(i, { x: bx, y: by, w: s.w, h: s.h });
      // place members
      const c = components[i];
      if (!c.cyclic) {
        nodePos.set(c.members[0], { x: bx, y: by, w: s.w, h: 34, comp: i });
      } else {
        const cols = s.cols, cw = s.cw;
        c.members.forEach((m, k) => {
          const col = k % cols, row = Math.floor(k / cols);
          nodePos.set(m, { x: bx + PAD + col * (cw + GAP), y: by + COMP_LABEL + PAD + row * (34 + GAP), w: cw, h: 34, comp: i });
        });
      }
      x += s.w + COMP_GAP;
    }
  }
  // isolated region
  ... grid below ...
  return { nodePos, compBox, width, height, isoBoxes };
};
